import numpy as np
n=lambda v:v/np.linalg.norm(v)
atoms=[]
def add(e,p): atoms.append((e,np.array(p,float))); return len(atoms)-1
def perp(u,hint):
    p=hint-np.dot(hint,u)*u
    if np.linalg.norm(p)<1e-3: p=np.cross(u,[1,0.3,0.1])
    return n(p)
def addH(c,nbrs,k):
    C=atoms[c][1]; ds=[n(atoms[j][1]-C) for j in nbrs]
    if len(ds)==1:
        u=-ds[0]; p=perp(u,np.array([0.3,1,0.2])); q=np.cross(u,p)
        for t in range(3):
            a=2*np.pi*t/3; d=u*0.334+0.943*(np.cos(a)*p+np.sin(a)*q); add('H',C+1.09*d)
    else:
        b=-n(ds[0]+ds[1]); q=n(np.cross(ds[0],ds[1]))
        for s in (1,-1): add('H',C+1.09*(b*0.58+s*0.816*q))
Tc=add('Tc',[0,0,0])
r2=1/np.sqrt(2)
dirs={'up':[0,1,0],'down':[0,-1,0],'bl':[-r2,0,-r2],'br':[r2,0,-r2],'fl':[-r2,0,r2],'fr':[r2,0,r2]}
dirs={k:np.array(v) for k,v in dirs.items()}
# thiolates
for k,hint in (('up',[1,0,0]),('bl',[0,1,0])):
    u=dirs[k]; S=add('S',2.35*u); p=perp(u,np.array(hint,float))
    d=n(-u*np.cos(np.radians(105))+p*np.sin(np.radians(105)))
    d=n(u*0.26+p*0.966)
    C=add('C',atoms[S][1]+1.82*d); addH(C,[S],3)
# dmpe
for a,b in (('br','fr'),('fl','down')):
    u,v=dirs[a],dirs[b]
    P1=add('P',2.42*u);P2=add('P',2.42*v)
    M=(atoms[P1][1]+atoms[P2][1])/2; out=n(M)
    C1=add('C',M+out*1.3+0.77*n(atoms[P1][1]-atoms[P2][1]))
    C2=add('C',M+out*1.3-0.77*n(atoms[P1][1]-atoms[P2][1]))
    for P,w,Cb in ((P1,u,C1),(P2,v,C2)):
        Pp=atoms[P][1]; pb=perp(w,atoms[Cb][1]-Pp); q=np.cross(w,pb)
        for t in (1,2):
            ang=2*np.pi*t/3; d=w*0.42+0.906*(np.cos(ang)*pb+np.sin(ang)*q)
            Cm=add('C',Pp+1.83*d); addH(Cm,[P],3)
    addH(C1,[P1,C2],2); addH(C2,[P2,C1],2)
with open('init.xyz','w') as f:
    f.write(f"{len(atoms)}\nTc(SMe)2(dmpe)2\n")
    for e,p in atoms: f.write(f"{e} {p[0]:.4f} {p[1]:.4f} {p[2]:.4f}\n")
EOF
